// ---- crtc6845sv_vdc.sv
// crtc6845sv_vdc: MOS 8563 / 8568 VDC (Commodore 128 80-column): 6845-derived timing plus its video-RAM controller.
// Behaviour follows MAME mos8563.cpp (Curt Coder) on the mc6845 base (Wilbert Pol, Nigel Barnes).
// VARIANT: 8 = MOS 8563, 9 = MOS 8568 (R37 sync polarity, /INTR, CSYNC, status version 2).
// Where the C128 Programmer's Reference Guide and VICE agree against MAME, the docs win: R5 reads back bits 7:5 set,
// status bit 7 is low while any video-RAM transfer is pending, the cursor ends before line R11, cursor and character
// blink toggle every 8 / 16 frames, and the 8563 has no R37.
// VRAM: synchronous 64K x 8, VDI valid the CLOCK after VA. CLOCK must give at least 10 CLOCKs per character clock.
// DCLKEN: dot clock enable. RGBI / DE / HSYNC / VSYNC run one character (+1 dot) behind the timing counters;
// PIXCE marks the first dot of each pixel (every dot, or every second dot with pixel double).
module crtc6845sv_vdc #(parameter int VARIANT = 8)
(
    input  logic        CLOCK,
    input  logic        DCLKEN,
    input  logic        nRESET,
    input  logic        ENABLE,
    input  logic        R_nW,
    input  logic        RS,
    input  logic  [7:0] DI,
    output logic  [7:0] DO,
    input  logic        LPSTB,
    output logic [15:0] VA,
    output logic  [7:0] VDO,
    output logic        VWE,
    input  logic  [7:0] VDI,
    output logic  [3:0] RGBI,
    output logic        DE,
    output logic        PIXCE,
    output logic        HSYNC,
    output logic        VSYNC,
    output logic        VBLANK,
    output logic        nINTR,
    output logic        CSYNC
);

localparam bit V8568 = VARIANT == 9;

// ------------------------------------------------------------------ registers R0-R37
logic  [5:0] addr_reg;
logic  [7:0] r00, r01, r02, r03, r04, r06, r07, r12, r13, r14, r15, r18, r19, r20, r21, r22, r24, r25, r26, r27;
logic  [7:0] r30, r31d, r32, r33, r34, r35;
logic  [4:0] r05, r09, r11, r23, r29;
logic  [1:0] r08, r37;
logic  [6:0] r10;
logic  [3:0] r28, r36;                 // r28 = R28[7:4]
logic [15:0] lp_addr;
logic        lp_full;

wire [15:0] disp_start = {r12, r13};
wire [15:0] cur_addr   = {r14, r15};
wire [15:0] attr_start = {r20, r21};
wire [15:0] upd_addr   = {r18, r19};
wire  [8:0] row_step   = {1'b0, r01} + {1'b0, r27};
wire        dbl        = r25[4];
wire        bitmap     = r25[7];
wire        attr_en    = r25[6];
wire        semi       = r25[5];
wire        il         = r08 == 2'd3;
wire  [3:0] ctot       = r22[7:4];

// The timing state changes only on a character clock, at least 10 CLOCKs apart, so every next-state value below is
// computed from the current state and registered (p_*) one CLOCK ahead, then taken on the character clock.

// ------------------------------------------------------------------ character clock from the dot clock
logic [4:0] dcnt, dpc_m1_q;
wire  [4:0] dpc_m1 = dbl ? ((ctot == 4'd0) ? 5'd0 : {ctot, 1'b0} - 5'd1) : {1'b0, ctot};
wire        cclk   = DCLKEN & (dcnt >= dpc_m1_q);
always_ff @(posedge CLOCK) dpc_m1_q <= dpc_m1;
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET)
        dcnt <= 5'd0;
    else if (DCLKEN)
        dcnt <= (dcnt >= dpc_m1_q) ? 5'd0 : dcnt + 5'd1;
end

// ------------------------------------------------------------------ line timer (MAME mc6845 handle_line_timer, VDC flags)
logic  [7:0] h_cnt, len_m1, row;
logic  [4:0] raster, adj_cnt;
logic  [3:0] vs_cnt, hs_left;
logic        adj, vs_ff, vsync_q, line_en, row_end_q, field, started, hs;
logic  [5:0] blink_cnt, cblink_cnt;
logic        cursor_state, cblink_state;

logic       p_at_end;
wire        line_start = cclk & p_at_end;
logic [3:0] vs_cnt_a;  logic vs_ff_a, nvs_a;
logic [7:0] row_b;     logic [4:0] ras_b, adjc_b;  logic adj_b, line_en_b, nvs_b, vs_ff_b;  logic [3:0] vs_cnt_b;
logic       restart;   logic field_c; logic [4:0] ras_c; logic [7:0] row_c; logic line_en_c, nvs_c, vs_ff_c;
logic [3:0] vs_cnt_c;  logic [4:0] adjc_c; logic adj_c;
always_comb begin
    vs_ff_a = vs_ff; vs_cnt_a = vs_cnt; nvs_a = vsync_q;
    if (vs_ff) begin
        vs_cnt_a = vs_cnt + 4'd1;
        if (vs_cnt_a == r03[7:4]) begin vs_ff_a = 1'b0; nvs_a = 1'b0; end
    end
    row_b = row; ras_b = raster; adjc_b = adj_cnt; adj_b = adj; line_en_b = line_en; nvs_b = nvs_a;
    vs_ff_b = vs_ff_a; vs_cnt_b = vs_cnt_a;
    if (row_end_q) begin
        if (row == r04) begin adjc_b = 5'd0; adj_b = 1'b1; end
        ras_b = il ? {4'd0, ~(raster[0] ^ r09[0])} : 5'd0;
        row_b = row + 8'd1;
        if (row_b == r06) line_en_b = 1'b0;
        if (row_b == r07) begin vs_cnt_b = 4'd0; vs_ff_b = 1'b1; nvs_b = 1'b1; end
    end
    else
        ras_b = raster + (il ? 5'd2 : 5'd1);
    restart = 1'b0;
    field_c = field; ras_c = ras_b; row_c = row_b; line_en_c = line_en_b; nvs_c = nvs_b; vs_ff_c = vs_ff_b;
    vs_cnt_c = vs_cnt_b; adjc_c = adjc_b; adj_c = adj_b;
    if (~started | (adj_b & (adjc_b == r05))) begin
        restart = 1'b1;
        adj_c = 1'b0;
        field_c = il & ~field;
        ras_c = {4'd0, field_c};
        row_c = 8'd0;
        line_en_c = r06 != 8'd0;
        if (r07 == 8'd0) begin vs_cnt_c = 4'd0; vs_ff_c = 1'b1; nvs_c = 1'b1; end
    end
    else if (adj_b)
        adjc_c = adjc_b + 5'd1;
end

wire [5:0] blink_n  = blink_cnt + 6'd1;
wire [5:0] cblink_n = cblink_cnt + 6'd1;
wire       at_end   = ~started | (h_cnt == len_m1);
wire [7:0] h_next   = at_end ? 8'd0 : h_cnt + 8'd1;
wire [7:0] len_next = at_end ? r00 : len_m1;
logic [7:0] p_h_next, p_row_c;
logic [4:0] p_ras_c, p_adjc_c;
logic [3:0] p_vs_cnt_c;
logic       p_hs_hit, p_adj_c, p_line_en_c, p_vs_ff_c, p_nvs_c, p_field_c, p_row_end_n, p_restart;
wire row_end_n = il ? ((p_ras_c >= r09) | ((p_ras_c + 5'd1) == r09)) : (p_ras_c == r09);   // from the registered next raster
always_ff @(posedge CLOCK) begin
    p_at_end <= at_end; p_h_next <= h_next; p_hs_hit <= (h_next == r02) & (len_next >= r02);
    p_row_c <= row_c; p_ras_c <= ras_c; p_adjc_c <= adjc_c; p_adj_c <= adj_c; p_line_en_c <= line_en_c;
    p_vs_ff_c <= vs_ff_c; p_vs_cnt_c <= vs_cnt_c; p_nvs_c <= nvs_c; p_field_c <= field_c; p_row_end_n <= row_end_n;
    p_restart <= restart;
end
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        h_cnt <= 8'd0; len_m1 <= 8'd0; row <= 8'd0; raster <= 5'd0; adj_cnt <= 5'd0; adj <= 1'b0;
        vs_cnt <= 4'd0; vs_ff <= 1'b0; vsync_q <= 1'b0; line_en <= 1'b0; row_end_q <= 1'b0; field <= 1'b0;
        started <= 1'b0; blink_cnt <= 6'd0; cblink_cnt <= 6'd0; cursor_state <= 1'b0; cblink_state <= 1'b0;
        hs <= 1'b0; hs_left <= 4'd0;
    end
    else if (cclk) begin
        h_cnt <= p_h_next;
        if (line_start) begin
            len_m1 <= r00;
            row <= p_row_c; raster <= p_ras_c; adj_cnt <= p_adjc_c; adj <= p_adj_c; line_en <= p_line_en_c;
            vs_ff <= p_vs_ff_c; vs_cnt <= p_vs_cnt_c; vsync_q <= p_nvs_c; field <= p_field_c; row_end_q <= p_row_end_n;
            started <= 1'b1;
            if (p_restart) begin
                // MAME update_cursor_state (mc6845) and the 8563 character blink
                blink_cnt <= blink_n;
                case (r10[6:5])
                    2'd0: cursor_state <= 1'b1;
                    2'd1: cursor_state <= 1'b0;
                    2'd2: if (blink_cnt[3] != blink_n[3]) cursor_state <= ~cursor_state;
                    default: if (blink_cnt[4] != blink_n[4]) cursor_state <= ~cursor_state;
                endcase
                cblink_cnt <= cblink_n;
                if (r24[5] ? (cblink_cnt[4] != cblink_n[4]) : (cblink_cnt[3] != cblink_n[3]))
                    cblink_state <= ~cblink_state;
            end
        end
        // HSYNC from character R2 for R3[3:0] characters (0 = 16); a new start restarts the width
        if (p_hs_hit) begin
            hs <= 1'b1;
            hs_left <= r03[3:0] - 4'd1;
        end
        else if (hs) begin
            if (hs_left == 4'd0) hs <= 1'b0;
            else hs_left <= hs_left - 4'd1;
        end
    end
end

// ------------------------------------------------------------------ draw counters (MAME frame_start / set_vsync / start_draw_line)
logic [15:0] frame_disp, frame_attr, lat_disp, lat_attr, draw_addr, attr_row, bm_addr;
logic  [4:0] draw_ra, draw_row_ra;
logic  [7:0] draw_row;
logic        latched;
logic [15:0] ln_addr, ln_bm, ln_attr;  // the line being shown, recorded at its start
logic  [4:0] ln_ra;
logic        ln_shown;

// second precompute stage: built on the line timer's registered next state
wire [15:0] fd_n   = p_restart ? (latched ? lat_disp : disp_start) : frame_disp;
wire [15:0] fa_n   = p_restart ? (latched ? lat_attr : attr_start) : frame_attr;
wire        f_n    = p_field_c & il;
// R24[4:0] x (R1 + R27) by shift-add (no DSP block)
logic [13:0] vs_mul;
logic  [8:0] row_step_q;
logic  [4:0] vss_q;
logic [13:0] vs_a, vs_b, vs_c, vs_ab, vs_cd;
always_ff @(posedge CLOCK) begin
    row_step_q <= row_step;
    vss_q      <= r24[4:0];
    vs_a   <= (vss_q[0] ? {5'd0, row_step_q} : 14'd0) + (vss_q[1] ? {4'd0, row_step_q, 1'b0} : 14'd0);
    vs_b   <= (vss_q[2] ? {3'd0, row_step_q, 2'b0} : 14'd0) + (vss_q[3] ? {2'd0, row_step_q, 3'b0} : 14'd0);
    vs_c   <= vss_q[4] ? {1'd0, row_step_q, 4'b0} : 14'd0;
    vs_ab  <= vs_a + vs_b;
    vs_cd  <= vs_c;
    vs_mul <= vs_ab + vs_cd;
end
wire [15:0] rl_attr = (il & bitmap) ? fa_n - {7'd0, row_step} : fa_n - ((r04 == 8'hff) ? {8'd0, r01} : 16'd0);
wire        rl_keep = f_n & bitmap;
wire [15:0] c_addr = p_restart ? fd_n : draw_addr;
wire [15:0] c_attr = (p_restart & ~rl_keep) ? rl_attr : attr_row;
wire [15:0] c_bm   = (p_restart & ~rl_keep) ? (fd_n + {2'd0, vs_mul}) : bm_addr;
wire  [4:0] c_ra   = p_restart ? (r24[4:0] + {4'd0, f_n}) : draw_ra;
wire  [4:0] c_rra  = p_restart ? {4'd0, f_n} : draw_row_ra;
wire  [7:0] c_row  = p_restart ? 8'd0 : draw_row;
wire        shown  = c_row < r06;
wire        ra_last  = il ? ((c_ra >= r09) | ((c_ra + 5'd1) == r09)) : (c_ra == r09);
wire        rra_last = il ? ((c_rra >= r09) | ((c_rra + 5'd1) == r09)) : (c_rra == r09);
wire        adv      = shown | (il & (r06 < r04) & (c_row == r06) & ~rra_last);
logic [15:0] p_fd, p_fa, p_c_addr, p_c_attr, p_c_bm, p_addr_adv, p_attr_adv, p_bm_adv;
logic  [4:0] p_c_ra, p_c_rra, p_ra_next, p_rra_next;
logic  [7:0] p_c_row, p_row_inc;
logic        p_shown, p_adv, p_ra_last, p_rra_last, p_latch;
always_ff @(posedge CLOCK) begin
    p_fd <= fd_n; p_fa <= fa_n; p_latch <= ~p_line_en_c & (p_restart | ~latched);
    p_c_addr <= c_addr; p_c_attr <= c_attr; p_c_bm <= c_bm; p_c_ra <= c_ra; p_c_rra <= c_rra; p_c_row <= c_row;
    p_shown <= shown; p_adv <= adv; p_ra_last <= ra_last; p_rra_last <= rra_last;
    p_addr_adv <= c_addr + {7'd0, row_step}; p_attr_adv <= c_attr + {7'd0, row_step}; p_bm_adv <= c_bm + {7'd0, row_step};
    p_ra_next  <= ra_last ? (il ? {4'd0, ~(c_ra[0] ^ r09[0])} : 5'd0) : c_ra + (il ? 5'd2 : 5'd1);
    p_rra_next <= rra_last ? (il ? {4'd0, ~(c_rra[0] ^ r09[0])} : 5'd0) : c_rra + (il ? 5'd2 : 5'd1);
    p_row_inc  <= c_row + 8'd1;
end
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        frame_disp <= 16'd0; frame_attr <= 16'd0; lat_disp <= 16'd0; lat_attr <= 16'd0; latched <= 1'b0;
        draw_addr <= 16'd0; attr_row <= 16'd0; bm_addr <= 16'd0; draw_ra <= 5'd0; draw_row_ra <= 5'd0;
        draw_row <= 8'd0; ln_addr <= 16'd0; ln_bm <= 16'd0; ln_attr <= 16'd0; ln_ra <= 5'd0; ln_shown <= 1'b0;
    end
    else if (line_start) begin
        frame_disp <= p_fd;
        frame_attr <= p_fa;
        // start addresses latch at the first line of a frame with the display off
        if (p_latch) begin
            lat_disp <= disp_start;
            lat_attr <= attr_start;
            latched  <= 1'b1;
        end
        else if (p_restart)
            latched <= 1'b0;
        ln_addr <= p_c_addr; ln_bm <= p_c_bm; ln_attr <= p_c_attr; ln_ra <= p_c_ra; ln_shown <= p_shown;
        draw_addr <= p_c_addr; attr_row <= p_c_attr; bm_addr <= p_c_bm; draw_ra <= p_c_ra; draw_row_ra <= p_c_rra;
        draw_row <= p_c_row;
        if (p_adv) begin
            bm_addr <= p_bm_adv;
            draw_ra <= p_ra_next;
            if (p_ra_last) begin
                draw_addr <= p_addr_adv;
                attr_row  <= p_attr_adv;
            end
            draw_row_ra <= p_rra_next;
            if (p_rra_last) draw_row <= p_row_inc;
        end
    end
end

// ------------------------------------------------------------------ draw_row constants (MAME displayed_width / semigraphics_gap)
wire  [7:0] r22d = (dbl & ~r22[3] & (r22 >= 8'h10)) ? r22 - 8'h10 : r22;
function automatic [3:0] disp_w(input [7:0] x);
    logic [3:0] t, d;
    logic [4:0] s;
    begin
        t = x[7:4]; d = x[3:0]; s = {1'b0, d} + {1'b0, t} - 5'd6;
        if (t < 4'd8)
            disp_w = (d < t) ? d + 4'd1 : (d == t) ? 4'd0 : t + 4'd1;
        else if (d < 4'd7)
            disp_w = (s > 5'd8) ? 4'd8 : s[3:0];
        else if (d == 4'd7)
            disp_w = 4'd0;
        else
            disp_w = (d <= t) ? d - 4'd7 : 4'd8;
    end
endfunction
// static draw constants: two register stages (they follow register writes two CLOCKs later)
logic [3:0] dw0;
logic       semi_gapc;
always_ff @(posedge CLOCK) begin
    dw0 <= disp_w(r22d);
    semi_gapc <= (r22d[7:4] >= 4'd7) & (((r22d[3:0] < 4'd8) & ({1'b0, r22d[3:0]} + {1'b0, r22d[7:4]} <= 5'd14)) |
                                         ((r22d[3:0] >= 4'd8) & (r22d[3:0] <= r22d[7:4])));
end
logic [7:0] dmask_q, semi_test_q, semi_type_q, d2mask_q;
logic [4:0] cth_q;
logic       hs_bad_q, blank_q;
wire        semi_frc  = dbl & (r22[7:4] == r22[3:0]);
wire        semi_on   = semi | semi_frc;
wire  [3:0] dw        = semi_frc ? ((r22[3:0] <= 4'd8) ? 4'd1 : dw0) : (semi & (dw0 == 4'd0)) ? 4'd8 : dw0;
wire  [7:0] semi_test = semi_on ? (8'h80 >> (dw - 4'd1)) : 8'h00;
wire  [7:0] semi_type = semi_gapc ? 8'hff : 8'h00;
wire  [7:0] dmask     = ~(8'hff >> ((dw > 4'd8) ? 4'd8 : dw));
wire  [4:0] gap_tot   = {1'b0, r22[7:4]} - 5'd6;          // two's complement: negative when R22[7:4] < 6
wire        gap_on    = ~gap_tot[4] & (gap_tot > (dbl ? 5'd2 : 5'd1));
wire  [7:0] d2mask    = gap_on ? ~(8'hff >> ((gap_tot > 5'd8) ? 4'd8 : gap_tot[3:0])) : 8'h00;
wire  [4:0] cth       = {1'b0, ctot} + (dbl ? 5'd0 : 5'd1);
wire        hs_bad    = ({1'b0, r25[3:0]} + {4'd0, dbl}) > {1'b0, ctot};
wire        blank     = ((r34 > r00) | (r34 == r35)) & (r35 <= r00);
always_ff @(posedge CLOCK) begin
    dmask_q <= dmask; semi_test_q <= semi_test; semi_type_q <= semi_type; d2mask_q <= d2mask;
    cth_q <= cth; hs_bad_q <= hs_bad; blank_q <= blank;
end
wire        line_draw = ln_shown & ~blank_q & ~hs_bad_q;
// cursor for the current line: lines R10 .. R11 - 1 (start = end: that line; start > end wraps), as PRG / VICE
wire [15:0] cur_off   = cur_addr - ln_addr;
wire        cur_rows  = (r10[4:0] == r11) ? (ln_ra == r11) :
                        (r10[4:0] < r11)  ? ((ln_ra >= r10[4:0]) & (ln_ra < r11)) :
                                            ((ln_ra >= r10[4:0]) | (ln_ra < r11));
wire        cur_vis   = cursor_state & (cur_addr >= ln_addr) & ({1'b0, cur_addr} < {1'b0, ln_addr} + {9'd0, r01}) & cur_rows;
logic       cur_on_q;
logic [6:0] cur_col_q;
always_ff @(posedge CLOCK) begin
    cur_on_q  <= cur_vis & (cur_off[15:7] == 9'd0);
    cur_col_q <= cur_off[6:0];
end

// ------------------------------------------------------------------ video RAM port
typedef enum logic [2:0] { F_IDLE, F_CODE, F_ATTR, F_FONT, F_DONE } fstate_t;
fstate_t     fst;
logic  [8:0] col;                   // column being fetched this character (0..R1)
logic  [7:0] f_code, f_attr, f_font;
logic        m_busy;                // a read issued last CLOCK returns on VDI now
logic  [2:0] m_tag;                 // 1 code, 2 attr, 3 font, 4 R31 prefetch, 5 block source
logic        cpu_wr_req, pf_valid, blk_active, blk_tick, blk_rd_done;
logic [15:0] cpu_wr_addr, pf_addr;
logic  [7:0] cpu_wr_data, pf_data, blk_data;

wire [15:0] code_a = (bitmap ? ln_bm : ln_addr) + {7'd0, col};
wire [15:0] attr_a = ln_attr + {7'd0, col};
wire [15:0] font_a = (r09 < 5'd16) ? ({r28[3:1], 13'd0} + {3'd0, f_attr[7], 12'd0} + {4'd0, f_code, 4'd0} + {11'd0, ln_ra})
                                   : ({r28[3:2], 14'd0} + {2'd0, f_attr[7], 13'd0} + {3'd0, f_code, 5'd0} + {11'd0, ln_ra});

logic [15:0] va_n;
logic  [7:0] vdo_n;
logic        vwe_n, blk_wr;
logic  [2:0] tag_n;
always_comb begin
    va_n = 16'd0; vdo_n = 8'd0; vwe_n = 1'b0; tag_n = 3'd0; blk_wr = 1'b0;
    if (fst == F_CODE)                       begin if (!m_busy) begin va_n = code_a; tag_n = 3'd1; end end
    else if (fst == F_ATTR)                  begin if (!m_busy) begin va_n = attr_a; tag_n = 3'd2; end end
    else if (fst == F_FONT)                  begin if (!m_busy) begin va_n = font_a; tag_n = 3'd3; end end
    else if (cpu_wr_req)                     begin va_n = cpu_wr_addr; vdo_n = cpu_wr_data; vwe_n = 1'b1; end
    else if (blk_tick & r24[7] & ~blk_rd_done) begin if (!m_busy) begin va_n = {r32, r33}; tag_n = 3'd5; end end
    else if (blk_tick)                       begin va_n = upd_addr; vdo_n = r24[7] ? blk_data : r31d; vwe_n = 1'b1; blk_wr = 1'b1; end
    else if (~pf_valid & ~blk_active & ~m_busy) begin va_n = upd_addr; tag_n = 3'd4; end
end
// R28 bit 4 clear: 4416 (16K) address wiring
assign VA  = r28[0] ? va_n : {va_n[15], va_n[13:8], va_n[8], va_n[7:0]};
assign VDO = vdo_n;
assign VWE = vwe_n;

// ------------------------------------------------------------------ host interface, R31 port, block engine
logic        acc_q;
wire         acc_new = ENABLE & ~acc_q;
logic  [7:0] rd_data;
always_comb begin
    case (addr_reg)
        6'h00: rd_data = r00;               6'h01: rd_data = r01;               6'h02: rd_data = r02;
        6'h03: rd_data = r03;               6'h04: rd_data = r04;               6'h05: rd_data = {3'b111, r05};
        6'h06: rd_data = r06;               6'h07: rd_data = r07;               6'h08: rd_data = {6'h3f, r08};
        6'h09: rd_data = {3'b111, r09};     6'h0a: rd_data = {1'b1, r10};       6'h0b: rd_data = {3'b111, r11};
        6'h0c: rd_data = r12;               6'h0d: rd_data = r13;               6'h0e: rd_data = r14;
        6'h0f: rd_data = r15;               6'h10: rd_data = lp_addr[15:8];     6'h11: rd_data = lp_addr[7:0];
        6'h12: rd_data = r18;               6'h13: rd_data = r19;               6'h14: rd_data = r20;
        6'h15: rd_data = r21;               6'h16: rd_data = r22;               6'h17: rd_data = {3'b111, r23};
        6'h18: rd_data = r24;               6'h19: rd_data = r25;               6'h1a: rd_data = r26;
        6'h1b: rd_data = r27;               6'h1c: rd_data = {r28, 4'hf};       6'h1d: rd_data = {3'b111, r29};
        6'h1e: rd_data = r30;               6'h1f: rd_data = pf_data;           6'h20: rd_data = r32;
        6'h21: rd_data = r33;               6'h22: rd_data = r34;               6'h23: rd_data = r35;
        6'h24: rd_data = {4'hf, r36};       6'h25: rd_data = V8568 ? {r37, 6'h3f} : 8'hff;
        default: rd_data = 8'hff;
    endcase
end
wire        ready  = ~(blk_active | cpu_wr_req | ~pf_valid);
wire  [7:0] status = {ready, lp_full, ~line_en, 3'd0, V8568 ? 2'd2 : 2'd1};

// 8568 /INTR: low from an Update Ready 0 -> 1 edge until a status read or Update Ready falls
logic ready_q, intr;
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        ready_q <= 1'b0;
        intr    <= 1'b0;
    end
    else if (V8568) begin
        ready_q <= ready;
        if (~ready | (acc_new & R_nW & ~RS)) intr <= 1'b0;
        else if (~ready_q) intr <= 1'b1;
    end
end
assign nINTR = ~(V8568 & intr);
assign CSYNC = V8568 ? (HSYNC ~^ VSYNC) : 1'b1;

// light pen: the 6845 refresh address (row start + R1 per row) one character after the strobe
logic [15:0] base_row;
logic        lp_q, lp_pend;
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET)
        base_row <= 16'd0;
    else if (line_start)
        base_row <= p_restart ? disp_start : row_end_q ? base_row + {8'd0, r01} : base_row;
end

always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        addr_reg <= 6'd0; DO <= 8'h00; acc_q <= 1'b0;
        r00 <= 8'd0; r01 <= 8'd0; r02 <= 8'd0; r03 <= 8'd0; r04 <= 8'd0; r05 <= 5'd0; r06 <= 8'd0; r07 <= 8'd0;
        r08 <= 2'd0; r09 <= 5'd0; r10 <= 7'd0; r11 <= 5'd0; r12 <= 8'd0; r13 <= 8'd0; r14 <= 8'd0; r15 <= 8'd0;
        r18 <= 8'd0; r19 <= 8'd0; r20 <= 8'd0; r21 <= 8'd0; r22 <= 8'h78; r23 <= 5'd0; r24 <= 8'd0; r25 <= 8'd0;
        r26 <= 8'd0; r27 <= 8'd0; r28 <= 4'd0; r29 <= 5'd0; r30 <= 8'd0; r31d <= 8'd0; r32 <= 8'd0; r33 <= 8'd0;
        r34 <= 8'd0; r35 <= 8'd0; r36 <= 4'd0; r37 <= 2'b11;
        lp_addr <= 16'd0; lp_full <= 1'b0; lp_q <= 1'b0; lp_pend <= 1'b0;
        cpu_wr_req <= 1'b0; cpu_wr_addr <= 16'd0; cpu_wr_data <= 8'd0; pf_addr <= 16'd0;
        pf_valid <= 1'b0; pf_data <= 8'd0;
        blk_active <= 1'b0; blk_tick <= 1'b0; blk_rd_done <= 1'b0; blk_data <= 8'd0;
    end
    else begin
        acc_q <= ENABLE;
        if (tag_n == 3'd4) pf_addr <= upd_addr;
        if (m_busy && m_tag == 3'd4 && pf_addr == upd_addr) begin pf_data <= VDI; pf_valid <= 1'b1; end
        if (m_busy && m_tag == 3'd5) begin blk_data <= VDI; blk_rd_done <= 1'b1; end
        if (vwe_n & ~blk_wr) cpu_wr_req <= 1'b0;
        // block fill / copy: one byte per character clock (MAME block_copy_tick)
        if (blk_wr) begin
            blk_tick <= 1'b0; blk_rd_done <= 1'b0;
            {r18, r19} <= upd_addr + 16'd1;
            pf_valid <= 1'b0;
            if (r24[7]) {r32, r33} <= {r32, r33} + 16'd1;
            r30 <= r30 - 8'd1;
            if (r30 == 8'd1) blk_active <= 1'b0;
        end
        if (cclk & blk_active & ~(blk_wr & (r30 == 8'd1))) blk_tick <= 1'b1;
        if (cclk) begin
            lp_q <= LPSTB;
            lp_pend <= LPSTB & ~lp_q;
            if (lp_pend) begin
                lp_addr <= base_row + {8'd0, h_cnt};
                lp_full <= 1'b1;
            end
        end
        if (acc_new) begin
            if (R_nW) begin
                DO <= RS ? rd_data : status;
                if (RS && (addr_reg == 6'h10 || addr_reg == 6'h11)) lp_full <= 1'b0;
                if (RS && addr_reg == 6'h1f) begin {r18, r19} <= upd_addr + 16'd1; pf_valid <= 1'b0; end
            end
            else if (!RS)
                addr_reg <= DI[5:0];
            else begin
                case (addr_reg)
                    6'h00: r00 <= DI;       6'h01: r01 <= DI;       6'h02: r02 <= DI;       6'h03: r03 <= DI;
                    6'h04: r04 <= DI;       6'h05: r05 <= DI[4:0];  6'h06: r06 <= DI;       6'h07: r07 <= DI;
                    6'h08: r08 <= DI[1:0];  6'h09: r09 <= DI[4:0];  6'h0a: r10 <= DI[6:0];  6'h0b: r11 <= DI[4:0];
                    6'h0c: r12 <= DI;       6'h0d: r13 <= DI;       6'h0e: r14 <= DI;       6'h0f: r15 <= DI;
                    6'h12: begin r18 <= DI; pf_valid <= 1'b0; end
                    6'h13: begin r19 <= DI; pf_valid <= 1'b0; end
                    6'h14: r20 <= DI;       6'h15: r21 <= DI;       6'h16: r22 <= DI;       6'h17: r23 <= DI[4:0];
                    6'h18: r24 <= DI;       6'h19: r25 <= DI;       6'h1a: r26 <= DI;       6'h1b: r27 <= DI;
                    6'h1c: begin r28 <= DI[7:4]; pf_valid <= 1'b0; end
                    6'h1d: r29 <= DI[4:0];
                    6'h1e: begin r30 <= DI; blk_active <= 1'b1; blk_tick <= 1'b0; blk_rd_done <= 1'b0; end
                    6'h1f: begin
                        r31d <= DI;
                        cpu_wr_req <= 1'b1; cpu_wr_addr <= upd_addr; cpu_wr_data <= DI;
                        {r18, r19} <= upd_addr + 16'd1; pf_valid <= 1'b0;
                    end
                    6'h20: r32 <= DI;       6'h21: r33 <= DI;       6'h22: r34 <= DI;       6'h23: r35 <= DI;
                    6'h24: r36 <= DI[3:0];  6'h25: if (V8568) r37 <= DI[7:6];
                    default: ;
                endcase
            end
        end
    end
end

// ------------------------------------------------------------------ fetch FSM: column c is fetched during character c
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        fst <= F_IDLE; col <= 9'd0; m_busy <= 1'b0; m_tag <= 3'd0; f_code <= 8'd0; f_attr <= 8'd0; f_font <= 8'd0;
    end
    else begin
        m_busy <= tag_n != 3'd0;
        m_tag  <= tag_n;
        if (m_busy && m_tag == 3'd1) f_code <= VDI;
        if (m_busy && m_tag == 3'd2) f_attr <= VDI;
        if (m_busy && m_tag == 3'd3) f_font <= VDI;
        if (cclk) begin
            col <= line_start ? 9'd0 : col + 9'd1;
            fst <= ((line_start ? 9'd0 : col + 9'd1) <= {1'b0, r01}) ? F_CODE : F_IDLE;
            f_attr <= 8'd0;
        end
        else begin
            case (fst)
                F_CODE: if (m_busy && m_tag == 3'd1) fst <= attr_en ? F_ATTR : bitmap ? F_DONE : F_FONT;
                F_ATTR: if (m_busy && m_tag == 3'd2) fst <= bitmap ? F_DONE : F_FONT;
                F_FONT: if (m_busy && m_tag == 3'd3) fst <= F_DONE;
                default: ;
            endcase
        end
    end
end

// column result (MAME draw_row, per column)
logic [7:0] c_d0, c_d1, c_d2, c_d3, c_g1, c_g2, c_g3;
logic [3:0] c_fg, c_bg;
always_comb begin
    c_fg = r26[7:4]; c_bg = r26[3:0]; c_g1 = 8'h00;
    if (bitmap) begin
        if (attr_en) begin c_fg = f_attr[3:0]; c_bg = f_attr[7:4]; end
        c_d1 = ((ln_ra > r23) ? 8'h00 : f_code) & dmask_q;
    end
    else begin
        if (attr_en) c_fg = f_attr[3:0];
        c_d1 = ((ln_ra > r23) ? 8'h00 : f_font) & dmask_q;
        if (f_attr[5] && ln_ra == r29) begin c_d1 = 8'hff; c_g1 = 8'hff; end
        if (f_attr[4] && !cblink_state) begin c_d1 = 8'h00; c_g1 = 8'h00; end
    end
    c_d2 = c_d1; c_g2 = c_g1;
    if ((c_d1 & semi_test_q) != 8'h00) begin c_d2 = c_d1 | (semi_test_q - 8'd1); c_g2 = semi_type_q; end
    c_d3 = c_d2; c_g3 = c_g2;
    if (!bitmap) begin
        if (f_attr[6]) begin c_d3 = ~c_d3; c_g3 = ~c_g3; end
        if (cur_on_q && {2'b00, cur_col_q} == col) begin c_d3 = ~c_d3; c_g3 = ~c_g3; end
    end
    c_d0 = r24[6] ? ~c_d3 : c_d3;
end

logic [7:0] q_d, q_g;
logic [3:0] q_fg, q_bg;
logic       q_ok;
always_ff @(posedge CLOCK) begin
    q_d  <= c_d0;
    q_g  <= (r24[6] ? ~c_g3 : c_g3) & d2mask_q;
    q_fg <= c_fg; q_bg <= c_bg;
    q_ok <= (fst == F_DONE) & ~cclk;
end

// ------------------------------------------------------------------ pixel output, one character behind the fetch
logic  [7:0] s_data, s_gap;
logic  [3:0] s_fg, s_bg;
logic        s_live, s_hs, s_vs, s_vb;
logic  [4:0] s_dot;
logic signed [13:0] s_x;           // window coordinate of the next pixel
logic [12:0] wend;                 // R1 x cth
logic [12:0] we_a, we_b, we_c, we_ab, we_cd;
always_ff @(posedge CLOCK) begin
    we_a <= (cth_q[0] ? {5'd0, r01} : 13'd0) + (cth_q[1] ? {4'd0, r01, 1'b0} : 13'd0);
    we_b <= (cth_q[2] ? {3'd0, r01, 2'b0} : 13'd0) + (cth_q[3] ? {2'd0, r01, 3'b0} : 13'd0);
    we_c <= cth_q[4] ? {1'd0, r01, 4'b0} : 13'd0;
    we_ab <= we_a + we_b;
    we_cd <= we_c;
    wend  <= we_ab + we_cd;
end
wire  [4:0] pix   = dbl ? {1'b0, s_dot[4:1]} : s_dot;
wire  [7:0] bits  = (pix < 5'd8) ? s_data : s_gap;
wire        on    = bits[3'd7 - pix[2:0]];
wire        in_w  = s_live & ~s_x[13] & (s_x < $signed({1'b0, wend})) & (pix < cth_q);
wire        first = ~dbl | ~s_dot[0];
always_ff @(posedge CLOCK or negedge nRESET) begin
    if (!nRESET) begin
        s_data <= 8'd0; s_gap <= 8'd0; s_fg <= 4'd0; s_bg <= 4'd0; s_live <= 1'b0; s_dot <= 5'd0; s_x <= 14'sd0;
        s_hs <= 1'b0; s_vs <= 1'b0; s_vb <= 1'b1;
        RGBI <= 4'd0; DE <= 1'b0; PIXCE <= 1'b0; HSYNC <= 1'b0; VSYNC <= 1'b0; VBLANK <= 1'b1;
    end
    else if (DCLKEN) begin
        RGBI  <= in_w ? (on ? s_fg : s_bg) : r26[3:0];
        DE    <= in_w;
        PIXCE <= first;
        HSYNC <= V8568 ? (s_hs ~^ r37[1]) : s_hs;
        VSYNC <= V8568 ? (s_vs ~^ r37[0]) : s_vs;
        VBLANK <= s_vb;
        if (cclk) begin
            s_data <= q_d;
            s_gap  <= q_g;
            s_fg <= q_fg; s_bg <= q_bg;
            s_live <= q_ok & (fst == F_DONE) & line_draw & (col <= {1'b0, r01});
            s_x <= (col == 9'd0) ? $signed({10'd0, r25[3:0]}) - $signed({9'd0, cth_q}) + 14'sd1 : s_x + 14'sd1;
            s_dot <= 5'd0;
            s_hs <= hs; s_vs <= vsync_q; s_vb <= ~line_en;
        end
        else begin
            s_dot <= s_dot + 5'd1;
            if (~dbl | s_dot[0]) s_x <= s_x + 14'sd1;
        end
    end
end

endmodule
